package com.mfg.qms.entity;import jakarta.persistence.*;import lombok.*;import java.math.*;import java.time.*;
@Entity @Table(name="qms_defect",catalog="src_qms") @Getter @Setter @NoArgsConstructor public class DefectRecord{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="defect_no")private String defectNo;@Column(name="inspection_no")private String inspectionNo;@Column(name="material_code")private String materialCode;@Column(name="defect_qty")private BigDecimal defectQty;@Column(name="defect_type")private String defectType;@Column(name="defect_desc")private String defectDesc;@Column(name="defect_level")private String defectLevel;@Column(name="disposition")private String disposition;@Column(name="disposition_qty")private BigDecimal dispositionQty=BigDecimal.ZERO;@Column(name="disposition_at")private LocalDateTime dispositionAt;@Column(name="disposition_by")private String dispositionBy;@Column(name="responsible_dept")private String responsibleDept;@Column(name="root_cause")private String rootCause;}
